This allows cases like:

```
metadata = {
    "entities": [
        {"entity": "Bell", "type": "PEOPLE"},
        ...
    ]
}
```

Note: For stores that perform shredding this works by JSON encoding the entire item `{"entity": "Bell", "type": "PEOPLE"}` into the key. This means that equality on the items of `entities` are supported, by digging into fields won't be.

## DESCRIPTION
This pr adds support for parsing and interpreting enums.
It also adds the ability to retrieve the parameters of enums.

## NOTE
You can't use the enum field directly, meaning you need to use this syntax:
```haxe
EnumName.EnumField
```

## CODE
```haxe
enum TestEnum {
  CInt(v:Int);
  CFloat(v:Float);
  CString(v:String);
  CNone;
}

class TestClass {
  function test() {
    // this works
    var test1 = TestEnum.CNone;
    
    switch (test1)
    {
      case TestEnum.CInt(v):
        trace('TestEnum.CInt(' + v + ')');
      case TestEnum.CFloat(v):
        trace('TestEnum.CFloat(' + v + ')');
      case TestEnum.CString(v):
        trace('TestEnum.CString(' + v + ')');
      case TestEnum.CNone:
        trace('TestEnum.CNone');
      default:
        trace('BRUH');
    }
    
    // this doesnt work
    var test2 = CNone;
    
    switch (test1)
    {
      case CInt(v):
        trace('TestEnum.CInt(' + v + ')');
      case CFloat(v):
        trace('TestEnum.CFloat(' + v + ')');
      case CString(v):
        trace('TestEnum.CString(' + v + ')');
      case CNone:
        trace('TestEnum.CNone');
      default:
        trace('BRUH');
    }
    
  }
}
```
